  function renderRadar() { const el = $('#radarChart'); if (!el) return; const metrics = [{ name: 'Prompt Craft', val: 72 }, { name: 'Process Depth', val: 65 }, { name: 'Tech Accuracy', val: 88 }, { name: 'Bug Detection', val: 75 }, { name: 'AI Guard', val: 60 }]; const cx = 90, cy = 90, r = 65; const n = metrics.length; const angleStep = (2 * Math.PI) / n; let grid = '<div class="radar-grid">'; for (let i = 5; i >= 1; i--) { const radius = (r / 5) * i; let pts = ''; for (let j = 0; j < n; j++) { const a = -Math.PI / 2 + j * angleStep; const x = cx + radius * Math.cos(a); const y = cy + radius * Math.sin(a); pts += x + ',' + y + ' '; } grid += '<polygon points="' + pts.trim() + '" />'; } grid += '</div>'; let axes = '<div class="radar-axis">'; for (let j = 0; j < n; j++) { const a = -Math.PI / 2 + j * angleStep; const x2 = cx + r * Math.cos(a); const y2 = cy + r * Math.sin(a); axes += '<line x1="' + cx + '" y1="' + cy + '" x2="' + x2 + '" y2="' + y2 + '" />'; } axes += '</div>'; let pts = ''; metrics.forEach((m, j) => { const a = -Math.PI / 2 + j * angleStep; const radius = (r / 100) * m.val; const x = cx + radius * Math.cos(a); const y = cy + radius * Math.sin(a); pts += x + ',' + y + ' '; }); let data = '<div class="radar-data"><polygon points="' + pts.trim() + '" />'; metrics.forEach((m, j) => { const a = -Math.PI / 2 + j * angleStep; const radius = (r / 100) * m.val; const x = cx + radius * Math.cos(a); const y = cy + radius * Math.sin(a); data += '<circle cx="' + x + '" cy="' + y + '" r="3" />'; }); data += '</div>'; let labels = '<div class="radar-labels">'; metrics.forEach((m, j) => { const a = -Math.PI / 2 + j * angleStep; const lx = cx + (r + 18) * Math.cos(a); const ly = cy + (r + 18) * Math.sin(a); labels += '<div class="radar-label" style="left:' + lx + 'px; top:' + ly + 'px; text-align:center">' + esc(m.name) + '</div>'; }); labels += '</div>'; el.innerHTML = '<svg width="180" height="180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:100%">' + grid + axes + data + '</svg>' + labels; }
  function renderCodeCascade() { const el = $('#codeCascade'); if (!el) return; const lines = [{ hash: '0x3a7f', op: 'READ', addr: '0x7f8a', data: 'session_id=42 → prompt_hash=sha256(abc123...)', status: 'ok' }, { hash: '0x3a80', op: 'WRITE', addr: '0x7f8b', data: 'unique_prompts INSERT prompt_hash=abc123', status: 'ok' }, { hash: '0x3a81', op: 'CALL', addr: '0x7f8c', data: 'ai_service.judge_prompt() → craft=0.72, depth=0.65', status: 'ok' }, { hash: '0x3a82', op: 'WRITE', addr: '0x7f8d', data: 'prompt_logs INSERT iteration=1, tokens=180', status: 'ok' }, { hash: '0x3a83', op: 'READ', addr: '0x7f8e', data: 'session_analytics SELECT final_score', status: 'ok' }, { hash: '0x3a84', op: 'ALERT', addr: '0x7f8f', data: 'CRITICAL: prompt_craft < 0.5 — depth_anomaly_detected', status: 'err' }, { hash: '0x3a85', op: 'WRITE', addr: '0x7f90', data: 'internal_analytics UPDATE final_metrics', status: 'ok' }, { hash: '0x3a86', op: 'COMMIT', addr: '0x7f91', data: 'transaction_complete final_score=78.5', status: 'ok' }]; el.innerHTML = lines.map((l) => '<div class="code-line"><span class="hash">' + l.hash + '</span> <span class="op">' + l.op + '</span> <span class="addr">' + l.addr + '</span> <span class="data">' + esc(l.data) + '</span> <span class="alert">' + (l.status === 'err' ? '⚠ ' + l.data : '') + '</span></div>').join(''); }

  // ═══════════════════ КАБИНЕТ РАБОТОДАТЕЛЯ ═══════════════════
  function renderEmployerView() { renderCompanySelect(); renderVacancyBuilder(); renderCandidatesTable(); renderSkillDistribution(); renderMatchScores(); renderIndustryClassification(); renderDataStream(); renderHeatmap(); renderTimeline(); renderRadar(); renderCodeCascade(); }
  function renderCompanySelect() { const sel = $('#vacancyCompany'); if (!sel) return; sel.innerHTML = DATA.companies.map((c) => '<option value="' + c.id + '">' + esc(c.name) + ' — ' + esc(c.position) + '</option>').join(''); }
  function renderVacancyBuilder() { const wrap = $('#vacancySliders'); if (!wrap) return; const allWeights = {}; DATA.companies.forEach((c) => { Object.entries(c.weights).forEach(([skill, weight]) => { allWeights[skill] = Math.max(allWeights[skill] || 0, weight); }); }); const entries = Object.entries(allWeights).slice(0, 12); wrap.innerHTML = entries.map((el) => { const skill = el[0]; const weight = el[1]; return '<div class="slider-row"><div class="slider-label">' + esc(skillById(skill).name) + '</div><input type="range" min="0" max="100" value="' + weight + '" class="slider-input" data-skill="' + skill + '" /><div class="slider-value" data-value="' + skill + '">' + weight + '%</div></div>'; }).join(''); wrap.querySelectorAll('.slider-input').forEach((slider) => { slider.addEventListener('input', () => { const val = parseInt(slider.value, 10); const skill = slider.dataset.skill; const valueEl = wrap.querySelector('[data-value="' + skill + '"]'); if (valueEl) valueEl.textContent = val + '%'; const companyId = $('#vacancyCompany').value; const company = DATA.companies.find((c) => c.id === companyId); if (company && company.weights[skill] !== undefined) { company.weights[skill] = val; } }); }); }
