  function renderCandidatesTable() { const tbody = $('#candidatesTableBody'); if (!tbody) return; if (!state.candidates || state.candidates.length === 0) generateDemoCandidates(); const selectedCompanyId = $('#dashCompanyFilter').value; const hideLowCheckbox = $('#hideLowMatches'); const hideLow = hideLowCheckbox ? hideLowCheckbox.checked : false; let list = state.candidates; if (selectedCompanyId !== 'all') { list = list.filter((c) => c.matches.some((m) => m.company.id === selectedCompanyId)); } if (hideLow) list = list.filter((c) => c.score >= 50); const rows = list.map((c) => { const best = c.matches[0] || { company: DATA.companies[0] }; const com = best.company; const statusLabel = com.vacancyStatus === 'pending_expire' ? (state.lang === 'ru' ? '⚠ На грани скрытия' : state.lang === 'de' ? '⚠ Kurz vor dem Ausblenden' : '⚠ About to be hidden') : com.vacancyStatus === 'archived' ? (state.lang === 'ru' ? 'Архив' : state.lang === 'de' ? 'Archiv' : 'Archived') : (state.lang === 'ru' ? 'Активна' : state.lang === 'de' ? 'Aktiv' : 'Active'); const statusClass = com.vacancyStatus === 'pending_expire' ? 'pending' : com.vacancyStatus === 'archived' ? 'archived' : 'confirmed'; return { c: c, com: com, score: best.match != null ? best.match : c.score, statusLabel: statusLabel, statusClass: statusClass }; }).sort((a, b) => b.score - a.score); if (rows.length === 0) { tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; padding:40px; color:var(--text-muted)">' + t('no_candidates') + '</td></tr>'; return; } tbody.innerHTML = rows.map((t) => '<tr><td><div class="candidate-cell"><div class="candidate-avatar">' + esc((t.c.name || 'А')[0]) + '</div><div><div class="candidate-name">' + esc(t.c.name) + '</div><div class="candidate-email">' + esc(t.c.email) + '</div></div></div></td><td><strong>' + esc(t.com.name) + '</strong><div style="font-size:12px; color:var(--text-muted)">' + esc(t.com.position) + '</div></td><td><span class="c-score ' + scoreClass(t.score) + '">' + t.score + '%</span></td><td><div class="skills-tags">' + t.c.skills.slice(0, 3).map((s) => '<span class="skill-tag">' + esc(s.name) + '</span>').join('') + '</div></td><td><span class="vacancy-status ' + t.statusClass + '">' + t.statusLabel + '</span></td><td><button class="btn btn-outline btn-small" data-open="' + esc(t.c.email) + '">' + (state.lang === 'ru' ? 'Открыть' : state.lang === 'de' ? 'Öffnen' : 'Open') + '</button></td></tr>').join(''); tbody.querySelectorAll('[data-open]').forEach((btn) => { btn.addEventListener('click', () => { const cand = state.candidates.find((c) => c.email === btn.dataset.open); if (cand) openCandidateModal(cand); }); }); }
  function generateDemoCandidates() { const demos = [{ name: 'Мария С.', email: 'maria@skill.dev', skills: ['python', 'fastapi', 'llm', 'sql'] }, { name: 'Дмитрий К.', email: 'dmitry@skill.dev', skills: ['go', 'docker', 'kubernetes', 'algorithms'] }, { name: 'Ирина Л.', email: 'irina@skill.dev', skills: ['figma', 'uiux', 'css', 'llm'] }, { name: 'Владимир Р.', email: 'vlad@skill.dev', skills: ['python', 'postgresql', 'microservices'] }]; state.candidates = demos.map((d) => { const skillMap = {}; d.skills.forEach((id) => (skillMap[id] = 70 + Math.round(Math.random() * 30))); const matches = DATA.companies.filter((com) => Object.keys(com.weights).some((w) => skillMap[w] !== undefined)).map((com) => { let total = 0; let sum = 0; for (const [k, v] of Object.entries(com.weights)) { if (skillMap[k] !== undefined) { total += v; sum += v * skillMap[k]; } } return { company: com, match: total > 0 ? Math.round(sum / total) : 0, skillMap: skillMap }; }).sort((a, b) => b.match - a.match); const score = matches[0] ? matches[0].match : 55; const best = matches[0] ? matches[0].company : null; return { name: d.name, email: d.email, skills: d.skills.map(skillById), skillMap: skillMap, score: score, matches: matches, history: [{ company: best ? best.name : '—', prompt: (state.lang === 'ru' ? 'Промпт кандидата для кейса «' : state.lang === 'de' ? 'Kandidaten-Prompt für den Fall «' : 'Candidate prompt for case «') + (best ? best.position : '—') + '»: ' + (state.lang === 'ru' ? 'собрал уточняющие вопросы, проверил галлюцинации ИИ, предложил архитектуру решения.' : state.lang === 'de' ? 'sammelte Rückfragen, prüfte KI-Halluzinationen, schlug Lösungsarchitektur vor.' : 'gathered clarifying questions, checked AI hallucinations, proposed solution architecture.'), score: score }] }; }); }
  function openCandidateModal(cand) { const modal = $('#candidateModal'); const content = $('#candidateModalContent'); if (!modal || !content) return; const best = cand.matches[0] ? cand.matches[0].company : DATA.companies[0]; content.innerHTML = '<div class="candidate-detail-header"><div><h2>' + esc(cand.name) + '</h2><div class="candidate-detail-sub">' + esc(cand.email) + ' · ' + cand.skills.map((s) => esc(s.name)).join(', ') + '</div></div><span class="c-score ' + scoreClass(cand.score) + '">' + cand.score + '%</span></div><div class="card" style="background:var(--bg-deep); margin-bottom:12px"><h3 style="color:var(--amber)">📊 ' + (state.lang === 'ru' ? 'Матрица совпадения' : state.lang === 'de' ? 'Übereinstimmungsmatrix' : 'Match matrix') + '</h3><div style="margin-top:14px">' + cand.matches.slice(0, 3).map((m) => '<div class="match-bar-row"><div class="match-label">' + esc(m.company.name) + '</div><div class="match-bar-track"><div class="match-bar-fill" style="width:' + m.match + '%"></div></div><div class="match-bar-value">' + m.match + '%</div></div>').join('') + '</div></div><div class="card" style="background:var(--bg-deep)"><h3 style="color:var(--amber)">🧠 ' + (state.lang === 'ru' ? 'История промптов / ход мысли' : state.lang === 'de' ? 'Prompt-Historie / Gedanken' : 'Prompt history / thought process') + '</h3><pre style="background:var(--bg); padding:14px; border-radius:4px; margin-top:10px; font-size:12.5px; color:var(--text); white-space:pre-wrap; font-family:var(--mono)">' + esc(cand.history[0] ? cand.history[0].prompt : '') + '</pre></div><div style="display:flex; gap:12px; margin-top:20px; flex-wrap:wrap"><button class="btn btn-primary">' + (state.lang === 'ru' ? 'Пригласить на интервью' : state.lang === 'de' ? 'Zum Interview einladen' : 'Invite to interview') + '</button><button class="btn btn-ghost">' + (state.lang === 'ru' ? 'Отклонить' : state.lang === 'de' ? 'Ablehnen' : 'Reject') + '</button></div>'; modal.style.display = 'flex'; }
